<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/espocrm/bootstrap.php';
use Espo\Core\{Application,AclManager,InjectableFactory};
use Espo\Core\ORM\EntityManager;
use Espo\Core\Tenant\{TenantContext,TenantContextStore};
use Espo\Core\Exceptions\{BadRequest,Conflict,Forbidden,NotFound};
use Espo\Custom\Tools\Conversation\{ChatStore,ConversationRoutingService};
$app=new Application();$app->setupSystemUser();$c=$app->getContainer();$em=$c->getByClass(EntityManager::class);$factory=$c->getByClass(InjectableFactory::class);$contexts=$c->getByClass(TenantContextStore::class);$store=$factory->create(ChatStore::class);
$a=new TenantContext('30000000-0000-4000-8000-000000000001','isolation-alpha','routing-test');$b=new TenantContext('30000000-0000-4000-8000-000000000002','isolation-beta','routing-test');$call=fn($fn)=>$contexts->runWith($a,$fn);$other=fn($fn)=>$contexts->runWith($b,$fn);
$checks=0;$assert=function(bool $ok,string $why)use(&$checks){$checks++;if(!$ok)throw new RuntimeException($why);};$deny=function(callable $fn,string $why)use($assert){try{$fn();}catch(BadRequest|Conflict|Forbidden|NotFound $error){$assert(true,$why);return;}$assert(false,$why);};
$tx=$em->getTransactionManager();$tx->start();
try{
    $suffix=bin2hex(random_bytes(6));$makeUser=fn($ctx,$type,$name)=>$contexts->runWith($ctx,function()use($em,$suffix,$type,$name){$u=$em->createEntity('User',['userName'=>'route-'.$name.'-'.$suffix,'emailAddress'=>'route-'.$name.'-'.$suffix.'@example.test','lastName'=>$name,'type'=>$type,'isActive'=>true]);return $em->getEntityById('User',$u->getId());});
    $admin=$makeUser($a,'admin','admin');$foreign=$makeUser($b,'admin','foreign');$alice=$makeUser($a,'regular','alice');$bob=$makeUser($a,'regular','bob');$hidden=$makeUser($a,'regular','hidden');
    $role=$call(fn()=>$em->createEntity('Role',['name'=>'Routing own '.$suffix,'data'=>['NexaChatConversation'=>['read'=>'own','edit'=>'own'],'NexaMessagingConversation'=>['read'=>'own','edit'=>'own']]]));
    $hiddenRole=$call(fn()=>$em->createEntity('Role',['name'=>'Routing hidden '.$suffix,'data'=>['NexaChatConversation'=>['read'=>'all','edit'=>'all']],'fieldData'=>['NexaChatConversation'=>['messages'=>['read'=>'no','edit'=>'no']]]]));
    foreach([$alice,$bob] as $u)$call(fn()=>$em->getRDBRepository('User')->getRelation($u,'roles')->relate($role));$call(fn()=>$em->getRDBRepository('User')->getRelation($hidden,'roles')->relate($hiddenRole));
    $team=$call(fn()=>$em->createEntity('Team',['name'=>'Routing queue '.$suffix]));foreach([$alice,$bob,$hidden] as $u)$call(fn()=>$em->getRDBRepository('Team')->getRelation($team,'users')->relate($u));
    $build=fn($u)=>$factory->createWith(ConversationRoutingService::class,['user'=>$u]);$settings=$build($admin);$foreignSettings=$build($foreign);$aliceService=$build($alice);$bobService=$build($bob);$hiddenService=$build($hidden);$worker=$factory->create(ConversationRoutingService::class);
    $deny(fn()=>$call(fn()=>$aliceService->process((object)['op'=>'workspace'])),'Regular staff cannot administer routing.');
    $deny(fn()=>$call(fn()=>$settings->run()),'Staff cannot invoke the routing worker.');
    $deny(fn()=>$other(fn()=>$settings->process((object)['op'=>'presence'])),'Presence cannot cross tenant scope.');
    $save=(object)['op'=>'save','channel'=>'chat','teamId'=>$team->getId(),'enabled'=>true,'capacity'=>1,'version'=>0];$call(fn()=>$settings->process($save));
    $deny(fn()=>$call(fn()=>$settings->process($save)),'Routing settings enforce optimistic concurrency.');
    $deny(fn()=>$other(fn()=>$foreignSettings->process((object)[...(array)$save,'version'=>0])),'Foreign teams cannot be used as routing queues.');
    $makeChat=fn($handoff=true)=>$call(fn()=>$em->createEntity('NexaChatConversation',['name'=>'Routing '.$suffix,'status'=>'Open','widgetId'=>ChatStore::uuid(),'origin'=>'http://localhost','tokenHash'=>bin2hex(random_bytes(32)),'visitorKeyHash'=>bin2hex(random_bytes(32)),'startNonce'=>ChatStore::uuid(),'expiresAt'=>gmdate('Y-m-d H:i:s',time()+3600),'handoffRequestedAt'=>$handoff?gmdate('Y-m-d H:i:s'):null]));
    $one=$makeChat();$two=$makeChat();$three=$makeChat();$bot=$makeChat(false);
    $assert($call(fn()=>$worker->run())===0,'No agent is implicitly available merely because their account exists.');
    $state=fn($id)=>$call(fn()=>$store->rows('SELECT assigned_user_id,routing_state FROM nexa_chat_conversation WHERE tenant_id=? AND service_id=? AND id=?',[...$store->scope(),$id]))[0];
    $assert($state($one->getId())['routing_state']==='waiting','No eligible available staff leaves a durable waiting state.');
    $available=fn($service)=>$call(fn()=>$service->process((object)['op'=>'presence','available'=>true,'version'=>0]));$aPresence=$available($aliceService);$bPresence=$available($bobService);$available($hiddenService);
    $assert($call(fn()=>$worker->run())===2,'Two available native-own agents receive no more than their configured capacity.');
    $owners=array_filter(array_map(fn($id)=>$state($id)['assigned_user_id'],[$one->getId(),$two->getId(),$three->getId()]));
    $assert(count(array_unique($owners))===2&&!in_array($hidden->getId(),$owners,true),'Least-loaded routing balances eligible staff and rejects hidden-message agents.');
    $assert($state($bot->getId())['assigned_user_id']===null,'Bot conversations are not stolen before a visitor handoff.');
    $assert($call(fn()=>$worker->run())===0,'Repeated worker invocations do not overwrite assigned records or exceed capacity.');
    $assigned=array_values(array_filter([$one,$two,$three],fn($root)=>$state($root->getId())['assigned_user_id']!==null));$waiting=array_values(array_filter([$one,$two,$three],fn($root)=>$state($root->getId())['assigned_user_id']===null))[0];
    $call(fn()=>$store->execute("UPDATE nexa_chat_conversation SET status='Closed' WHERE tenant_id=? AND service_id=? AND id=?",[...$store->scope(),$assigned[0]->getId()]));
    $assert($call(fn()=>$worker->run())===1&&$state($waiting->getId())['assigned_user_id']!==null,'Closing work releases capacity and the next worker drains the waiting queue.');
    $audit=$call(fn()=>$store->rows("SELECT COUNT(*) total FROM nexa_audit_event WHERE tenant_id=? AND service_id=? AND action='routing.assigned' AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json,'$.teamId'))=?",[...$store->scope(),$team->getId()]))[0]['total'];$assert((int)$audit===3,'Assignments have exactly one tenant-scoped routing audit each.');
    $away=$call(fn()=>$aliceService->process((object)['op'=>'presence','available'=>false,'version'=>$aPresence['version']]));$stale=$call(fn()=>$aliceService->process((object)['op'=>'presence','heartbeat'=>true,'version'=>$aPresence['version']]));$assert(!$away['available']&&!$stale['available'],'A stale heartbeat cannot undo explicit Away in another tab.');
    $call(fn()=>$store->execute('UPDATE nexa_conversation_presence SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 SECOND) WHERE tenant_id=? AND service_id=? AND user_id=?',[...$store->scope(),$bob->getId()]));$expired=$call(fn()=>$bobService->process((object)['op'=>'presence','heartbeat'=>true,'version'=>$bPresence['version']]));$assert(!$expired['available'],'Closing an inbox expires availability and stale heartbeats cannot resurrect it.');
    $four=$makeChat();$assert($call(fn()=>$worker->run())===0&&$state($four->getId())['assigned_user_id']===null,'Unavailable or full agents leave new requests queued.');
    $before=$state($waiting->getId());$other(fn()=>$worker->run());$assert($state($waiting->getId())===$before,'Another tenant worker cannot change existing ownership.');
    $manual=$makeChat();$call(fn()=>$store->execute('UPDATE nexa_chat_conversation SET assigned_user_id=? WHERE tenant_id=? AND service_id=? AND id=?',[$admin->getId(),...$store->scope(),$manual->getId()]));$call(fn()=>$worker->run());$assert($state($manual->getId())['assigned_user_id']===$admin->getId(),'Manual assignment takes precedence over automatic routing.');
    $public=$call(fn()=>$store->handoffState($em->getEntityById('NexaChatConversation',$waiting->getId())));$assert($public['state']==='assigned'&&$public['answeredAt']===null,'Assignment never masquerades as an actual staff reply.');
    $call(fn()=>$aliceService->process((object)['op'=>'presence','available'=>true,'version'=>$away['version']]));
    $call(fn()=>$em->getRDBRepository('Team')->getRelation($team,'users')->unrelate($alice));
    $assert($call(fn()=>$worker->run())===0,'Available staff outside the selected native Team cannot receive its queue.');
    $call(fn()=>$em->getRDBRepository('Team')->getRelation($team,'users')->relate($alice));
    $call(fn()=>$store->execute('UPDATE user SET is_active=0 WHERE tenant_id=? AND service_id=? AND id=?',[...$store->scope(),$alice->getId()]));
    $assert($call(fn()=>$worker->run())===0,'Deactivated staff are rejected even while their old presence lease is fresh.');
    $call(fn()=>$store->execute('UPDATE user SET is_active=1 WHERE tenant_id=? AND service_id=? AND id=?',[...$store->scope(),$alice->getId()]));
    $call(fn()=>$store->execute('UPDATE nexa_chat_conversation SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 SECOND) WHERE tenant_id=? AND service_id=? AND id=?',[...$store->scope(),$four->getId()]));
    $job=$factory->create(\Espo\Custom\Jobs\RouteConversations::class);$call(fn()=>$job->run());
    $assert($state($four->getId())['assigned_user_id']===null,'The actual native job ignores expired visitor sessions.');
    fwrite(STDOUT,"Conversation routing checks passed: {$checks} (rollback-only; no provider calls).\n");
}finally{$tx->rollback();}
